package clipboard

import (
	"net/url"
	"regexp"
	"strings"
	"unicode"
	"unicode/utf8"

	"wails-gui/internal/pii"
)

// Pasteboard types the rules read. The org.nspasteboard markers are the
// conventions documented at http://nspasteboard.org: password managers mark
// what they copy as concealed, clipboard tools mark short-lived and
// generated content as transient or auto-generated, and some apps name
// themselves as the source.
const (
	TypeConcealed     = "org.nspasteboard.ConcealedType"
	TypeTransient     = "org.nspasteboard.TransientType"
	TypeAutoGenerated = "org.nspasteboard.AutoGeneratedType"
	TypeSource        = "org.nspasteboard.source"
)

// Kinds of copy.
const (
	KindText  = "text"
	KindURL   = "url"
	KindFile  = "file"
	KindImage = "image"
	KindOther = "other"
)

// PreviewMaxRunes is the longest preview kept of a copied text.
const PreviewMaxRunes = 160

// ReadMaxUnits bounds how much of a copied text is read at all, in UTF-16
// code units: enough to redact and preview it, never a whole pasted
// document.
const ReadMaxUnits = 4096

// SkipTypes reports whether a copy with these pasteboard types must not be
// recorded at all: the copying app marked it concealed (a password),
// transient or auto-generated.
func SkipTypes(types []string) bool {
	for _, t := range types {
		switch t {
		case TypeConcealed, TypeTransient, TypeAutoGenerated:
			return true
		}
	}
	return false
}

var (
	fileTypes  = []string{"public.file-url", "NSFilenamesPboardType"}
	urlTypes   = []string{"public.url", "NSURLPboardType", "WebURLsWithTitlesPboardType"}
	imageTypes = []string{"public.png", "public.tiff", "public.jpeg", "public.heic", "com.compuserve.gif", "NSTIFFPboardType", "Apple PNG pasteboard type"}
	textTypes  = []string{"public.utf8-plain-text", "public.plain-text", "NSStringPboardType", "public.utf16-plain-text", "public.rtf", "public.html"}
)

func hasAny(types, want []string) bool {
	for _, t := range types {
		for _, w := range want {
			if t == w {
				return true
			}
		}
	}
	return false
}

// KindOf classifies a copy by its pasteboard types: a file wins over a link,
// a link over an image, an image over text.
func KindOf(types []string) string {
	switch {
	case hasAny(types, fileTypes):
		return KindFile
	case hasAny(types, urlTypes):
		return KindURL
	case hasAny(types, imageTypes):
		return KindImage
	case hasAny(types, textTypes):
		return KindText
	default:
		return KindOther
	}
}

// HasText reports whether the copy carries plain text a preview could come
// from.
func HasText(types []string) bool {
	return hasAny(types, textTypes) || hasAny(types, urlTypes)
}

// passwordManagerPrefixes are password managers missing from the sensitive
// apps list in internal/pii, which already covers 1Password, Bitwarden,
// LastPass, Dashlane, KeePassXC, Enpass, NordPass, RoboForm, Keychain Access
// and Passwords.
var passwordManagerPrefixes = []string{
	"com.keepersecurity",
	"com.markmcguill.strongbox",
	"me.proton.pass",
	"com.sinew.secrets",
	"com.apple.passwords",
}

// IsPasswordManager reports whether a copy came from a password manager, by
// bundle id or, for apps not listed, by a name that says so.
func IsPasswordManager(bundleID, appName string) bool {
	lower := strings.ToLower(strings.TrimSpace(bundleID))
	for _, prefix := range passwordManagerPrefixes {
		if lower != "" && strings.HasPrefix(lower, prefix) {
			return true
		}
	}
	name := strings.ToLower(appName)
	return strings.Contains(name, "password") || strings.Contains(name, "keychain")
}

// SensitiveSource reports whether copies from this app are never recorded:
// a password manager, or an app in the sensitive apps list (defaults plus
// the ones the user added on the Privacy page).
func SensitiveSource(bundleID, appName string) bool {
	if IsPasswordManager(bundleID, appName) {
		return true
	}
	if _, sensitive := pii.IsSensitiveApp(bundleID); sensitive {
		return true
	}
	return pii.IsSensitiveAppName(appName)
}

// WithholdPreview reports whether a copied text keeps no preview at all:
//   - one unbroken run without spaces that is not a web link, which is what
//     passwords, tokens, keys, codes and IDs look like;
//   - a recovery phrase: 12 to 25 lowercase words of letters only, as wallets
//     show them (BIP-39 and the like), numbered or not;
//   - any text that names a secret (a password, a passphrase, a PIN, a
//     recovery or seed phrase, a private or API key, a one-time or
//     verification code), since the words after the label may be the
//     secret.
//
// The few plain texts these also catch lose little.
func WithholdPreview(text string) bool {
	text = strings.TrimSpace(text)
	if text == "" {
		return true
	}
	if strings.IndexFunc(text, unicode.IsSpace) < 0 {
		return !IsLink(text)
	}
	return recoveryPhrase(text) || secretLabel.MatchString(text)
}

// secretLabel matches a word that says a secret follows or is nearby.
var secretLabel = regexp.MustCompile(`(?i)\b(?:pass(?:word|wd|phrase|code)s?|pwd|pin|secrets?|mnemonic|(?:seed|recovery|backup|secret)[ _-]?(?:phrase|words?|key|codes?)|private[ _-]?key|api[ _-]?key|access[ _-]?token|auth[ _-]?token|otp|2fa|(?:one[ -]?time|verification|security|login|sign[ -]?in|auth(?:entication)?)[ _-]?(?:code|pin))\b|密码|口令|助记词|验证码|私钥|恢复短语`)

// recoveryPhraseWords bounds a recovery phrase: 12 to 24 words (BIP-39), 25
// with a passphrase word or for Monero.
const (
	recoveryPhraseMinWords = 12
	recoveryPhraseMaxWords = 25
	recoveryPhraseMaxRunes = 8
)

// recoveryPhrase reports whether text is a run of short lowercase words of
// letters only, between 12 and 25 of them, ignoring "1." style numbering.
func recoveryPhrase(text string) bool {
	words := 0
	for _, field := range strings.Fields(text) {
		if strings.TrimRight(strings.TrimLeftFunc(field, unicode.IsDigit), ".):") == "" {
			continue // "1." "12)" "3:" numbering
		}
		if utf8.RuneCountInString(field) > recoveryPhraseMaxRunes {
			return false
		}
		for _, r := range field {
			if !unicode.IsLetter(r) || unicode.IsUpper(r) {
				return false
			}
		}
		words++
	}
	return words >= recoveryPhraseMinWords && words <= recoveryPhraseMaxWords
}

// IsLink reports whether a copied text is a single web link.
func IsLink(text string) bool {
	text = strings.TrimSpace(text)
	if text == "" || strings.IndexFunc(text, unicode.IsSpace) >= 0 {
		return false
	}
	u, err := url.Parse(text)
	return err == nil && (u.Scheme == "http" || u.Scheme == "https") && u.Host != ""
}

// LinkPreview keeps a link's scheme, host and plain path (pii.RedactURL).
func LinkPreview(text string) string {
	return pii.RedactURL(text)
}

// Preview is what is kept of a copied text: a link keeps only its scheme,
// host and plain path (LinkPreview); other text has its whitespace
// collapsed, personal details and keys replaced by pii.RedactText, every
// standalone run of 4 to 10 digits replaced, and is cut to PreviewMaxRunes.
// A single unbroken run (WithholdPreview) keeps no preview at all.
func Preview(text string) string {
	text = strings.Join(strings.Fields(strings.ToValidUTF8(text, "")), " ")
	if WithholdPreview(text) {
		return ""
	}
	if IsLink(text) {
		return cutPreview(LinkPreview(text))
	}
	redacted, _ := pii.RedactText(text)
	return cutPreview(pii.RedactCodes(redacted))
}

func cutPreview(text string) string {
	if utf8.RuneCountInString(text) <= PreviewMaxRunes {
		return text
	}
	runes := []rune(text)
	return strings.TrimSpace(string(runes[:PreviewMaxRunes])) + "..."
}
